import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
const source=await readFile(new URL('../../assets/journey-core.js',import.meta.url),'utf8');
const {tripState,sharedPlaceLabel,calendarDay,costSummary,money,parseMinor,archiveMoments,filterMoments}=await import('data:text/javascript;base64,'+Buffer.from(source).toString('base64'));
const trip={departureAt:'2026-10-28T00:00:00+01:00',timeZone:'Europe/Amsterdam',confirmedDepartureAt:null};
test('one millisecond before departure, exact transition and no fabricated departure',()=>{assert.equal(tripState(trip,Date.parse(trip.departureAt)-1).label,'Departing in <1 day');assert.equal(tripState(trip,Date.parse(trip.departureAt)).phase,'awaiting-confirmation');assert.equal(tripState(trip,Date.parse(trip.departureAt)+86400000).day,null);});
test('whole days match the main countdown and future confirmations do not start travel',()=>{assert.equal(tripState(trip,Date.parse(trip.departureAt)-7.5*86400000).label,'Departing in 7 days');assert.equal(tripState({...trip,confirmedDepartureAt:trip.departureAt},Date.parse(trip.departureAt)-1).phase,'planned');});
test('travel calendar day crosses midnight in reporting timezone, including DST',()=>{const departed={...trip,confirmedDepartureAt:'2026-10-24T23:30:00+02:00'};assert.equal(tripState(departed,Date.parse('2026-10-24T23:45:00+02:00')).day,1);assert.equal(tripState(departed,Date.parse('2026-10-25T00:15:00+02:00')).day,2);assert.equal(tripState(departed,Date.parse('2026-10-26T00:15:00+01:00')).day,3);assert.equal(calendarDay('2026-10-27T23:30:00Z','Europe/Amsterdam'),'2026-10-28');});
test('explicit undated confirmation shows underway without inventing a travel day',()=>{
  const confirmed={...trip,departureConfirmed:true};
  for(const now of ['2026-10-28T00:00:00Z','2026-11-05T12:00:00Z'])assert.deepEqual(tripState(confirmed,Date.parse(now)),{phase:'travelling',label:'On the move',remaining:0,day:null});
  for(const value of [false,1,'true',null])assert.equal(tripState({...trip,departureConfirmed:value},Date.parse('2026-11-05')).phase,'awaiting-confirmation');
  const completed=tripState({...confirmed,endedAt:'2026-11-01T12:00:00Z'},Date.parse('2026-11-05'));
  assert.equal(completed.phase,'completed');assert.equal(completed.day,null);
  assert.equal(tripState({...confirmed,confirmedDepartureAt:'2026-11-06T12:00:00Z'},Date.parse('2026-11-05')).phase,'awaiting-confirmation');
});
test('shared location may be an owner-approved country only, with no inferred city',()=>{
  assert.equal(sharedPlaceLabel({country:'Curaçao'}),'Curaçao');
  assert.equal(sharedPlaceLabel({country:'Test country',city:'Test city'}),'Test city, Test country');
  for(const location of [null,{},[],{city:'Test city'},{country:''},{country:'Test',city:''},{country:42},{country:'x'.repeat(101)}])assert.equal(sharedPlaceLabel(location),'');
});
test('ended trip, exact cents, zero/three decimal currencies and no floating point rounding',()=>{assert.equal(tripState({...trip,confirmedDepartureAt:'2026-10-01T00:00:00Z',endedAt:'2026-10-05T00:00:00Z'},Date.parse('2026-10-20')).phase,'completed');assert.equal(parseMinor('0.10','EUR')+parseMinor('0,20','EUR'),30);assert.equal(parseMinor('123','JPY'),123);assert.equal(parseMinor('1.234','BHD'),1234);assert.throws(()=>parseMinor('1.001','EUR'));assert.throws(()=>parseMinor('1.5','JPY'));assert.throws(()=>parseMinor('-1','EUR'));assert.equal(money(123,'JPY'),'JP¥123');});
test('partial coverage, shared costs, currencies and rounded daily average',()=>{const records=[{date:'2026-10-01',amountMinor:1001,personalMinor:500,currency:'EUR',category:'Food'},{date:'2026-10-03',amountMinor:201,personalMinor:101,currency:'EUR',category:'Transport'},{date:'2026-10-01',amountMinor:500,personalMinor:500,currency:'THB',category:'Food'}];const result=costSummary(records);assert.equal(result.length,2);assert.equal(result[0].totalMinor,1202);assert.equal(result[0].personalMinor,601);assert.equal(result[0].days,3);assert.equal(result[0].recordedDays,2);assert.equal(result[0].averageMinor,200);assert.equal(result[0].categories.Accommodation,undefined);assert.deepEqual(costSummary([]),[]);});
test('invalid expense and no zero-day average',()=>{assert.throws(()=>costSummary([{date:'bad',amountMinor:1,personalMinor:1,currency:'EUR',category:'Food'}]));assert.throws(()=>costSummary([{date:'2026-10-01',amountMinor:1,personalMinor:2,currency:'EUR',category:'Food'}]));});
test('public chronology contains only the owner-confirmed broad current location, no future itinerary',async()=>{const model=JSON.parse(await readFile(new URL('../../data/journey.json',import.meta.url),'utf8'));const moments=archiveMoments(model);assert.ok(moments.length>20);assert.ok(moments.every((m,i)=>!i||m.year>=moments[i-1].year));assert.equal(filterMoments(moments,{kind:'journal'}).length,3);assert.equal(filterMoments(moments,{year:'2099'}).length,0);assert.equal(model.expenses.length,0);const config=JSON.parse(await readFile(new URL('../../data/trip.json',import.meta.url),'utf8'));assert.deepEqual(config.revealedStops,[]);assert.deepEqual(config.currentLocation,{country:'Curaçao'});assert.equal(config.departureConfirmed,true);assert.equal(config.confirmedDepartureAt,null);assert.equal(config.timeZone,'Europe/Amsterdam');});
